{
  "subtype": "faceted_decomposition",
  "concept": "travel_policy_risk",
  "per_column": [
    {
      "name": "travel_policy_risk_flags",
      "is_constitutive_facet": false,
      "role": "restatement",
      "rationale": "This is a single multi-valued enumeration of specific risk instances bundled into one column, not a decomposition into distinct constitutive facets. It restates the whole concept (the set of identified risks) rather than carving it into non-overlapping aspects like risk type, severity, approval requirement, etc."
    },
    {
      "name": "travel_policy_risk_level",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "Severity/level is a genuine aspect OF a risk (a meronymic dimension), capturing the intensity facet of the concept."
    },
    {
      "name": "travel_policy_risk_count",
      "is_constitutive_facet": false,
      "role": "restatement",
      "rationale": "A count is a scalar summary/aggregate derived from the flags column, not a constitutive aspect of the risk concept itself. It measures how many risks, which is a magnitude of the whole rather than a distinct part-of facet."
    }
  ],
  "facet_columns": ["travel_policy_risk_level"],
  "non_facet_columns": ["travel_policy_risk_flags", "travel_policy_risk_count"],
  "mutual_exclusivity": 0.35,
  "exhaustiveness": 0.2,
  "rationale": "The columns do not constitute a proper MECE faceted decomposition of 'travel_policy_risk'. Only risk_level is a true facet (the severity dimension). The flags column bundles the entire concept into one multi-valued enumeration rather than splitting it into orthogonal aspects (e.g., risk category/type, approval authority required, monetary threshold, policy-violation status), and the count is merely a derived aggregate of the flags, overlapping with it and adding no distinct facet. Because two of three columns restate/derive from the whole, mutual exclusivity is weak and the constitutive aspects of the concept are largely uncovered."
}

